/**
 * 自托管产品演示视频（1600×900 / 16:9 WebM）
 * @author 恒哥
 */
import React from 'react';
import './product-video.css';

/**
 * @param {object} props
 * @param {string} props.src
 * @param {string} [props.title]
 * @param {string} [props.durationLabel]
 * @param {string} [props.className]
 * @param {boolean} [props.autoPlay]
 */
export default function ProductVideo({
  src,
  title = 'Whaleal Cart demo',
  durationLabel,
  className = '',
  autoPlay = false,
}) {
  if (!src) return null;

  return (
    <div className={`product-video ${className}`.trim()}>
      <div className="product-video-frame">
        <video
          className="product-video-el"
          controls
          playsInline
          preload="metadata"
          width={1600}
          height={900}
          title={title}
          aria-label={title}
          autoPlay={autoPlay}
        >
          <source src={src} type="video/webm" />
          Sorry, your browser does not support embedded video.
        </video>
      </div>
      {(title || durationLabel) && (
        <p className="product-video-caption">
          {durationLabel ? `${durationLabel} · ` : ''}
          {title}
        </p>
      )}
    </div>
  );
}
